class RegistryMeta(type):
    """Metaclass that registers subclasses in a registry dict."""

    def __init__(cls, name, bases, namespace):
        super().__init__(name, bases, namespace)
        if not hasattr(cls, 'registry'):
            cls.registry = {}
        else:
            cls.registry[name] = cls


class Base(metaclass=RegistryMeta):
    """Base class using RegistryMeta."""
    pass


class Foo(Base):
    pass


class Bar(Base):
    pass


# Usage
print(Base.registry)  # {'Foo': <class '__main__.Foo'>, 'Bar': <class '__main__.Bar'>}
print(Base.registry['Foo']())  # <__main__.Foo object at 0x...>
```

**How it works:**
- `RegistryMeta.__init__` runs when each class is created
- The first class (`Base`) initializes the `registry` dict
- Subsequent subclasses register themselves by name
- Access via `Base.registry['ClassName']`

