    let cancelled = false;

    setState({ status: 'loading' });

    fetch(url)
      .then(res => {
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        return res.json() as Promise<T>;
      })
      .then(data => {
        if (!cancelled) setState({ status: 'success', data });
      })
      .catch(err => {
        if (!cancelled) setState({ status: 'error', error: err });
      });

    return () => { cancelled = true; };
  }, [url]);

  return state;
}
```

